const test = require('node:test');
const assert = require('node:assert');
const { formatDay } = require('../date');
const { reminderSubject } = require('../email');
const { toCsvRow } = require('../export');

test('formatDay zero-pads month and day', () => {
  assert.strictEqual(formatDay(new Date(Date.UTC(2026, 2, 5))), '2026-03-05');
  assert.strictEqual(formatDay(new Date(Date.UTC(2026, 10, 26))), '2026-11-26');
});

test('reminder subject zero-pads the due date', () => {
  assert.strictEqual(
    reminderSubject('INV-1', new Date(Date.UTC(2026, 0, 9))),
    'Invoice INV-1 is due on 2026-01-09'
  );
});

test('csv row zero-pads the order date', () => {
  const row = toCsvRow({ id: 7, placedAt: new Date(Date.UTC(2026, 2, 5)), amount: 42 });
  assert.strictEqual(row, '7,2026-03-05,42');
});

